    let mut vowels = 0
    let mut consonants = 0
    for c in chars(s) {
        if is_vowel(c) {
            vowels += 1
        } else if c >= "a" && c <= "z" {
            consonants += 1
        }
    }
    LetterCount { vowels, consonants }
}

